    "}\n"
    "\n"
    "float3 ps_overlay(float3 d, float3 s, float a) {\n"
    "    const float3 one = float3(1.0, 1.0, 1.0);\n"
    "    float3 high = one - 2.0 * (one - s) * (one - d);\n"
    "    float3 low = 2.0 * d * s;\n"
    "    float3 r = float3(d.r < 0.5 ? low.r : high.r,\n"
    "                      d.g < 0.5 ? low.g : high.g,\n"
    "                      d.b < 0.5 ? low.b : high.b);\n"
    "    return ps_mix(d, r, a);\n"
    "}\n"
    "\n"
    "// Both snapshot and target-colour entries share exactly this 24-op body.\n"
    "float4 ps_apply(FragmentInput i, float4 d4) {\n"
    "    PsSample source = ps_source(i);\n"
    "    float4 t = source.texel;\n"
    "    float3 s = source.source;\n"
    "    float ca = source.opacity;\n"
    "    float a = source.alpha;\n"
    "    float3 d = d4.rgb;\n"
    "    const float3 one = float3(1.0, 1.0, 1.0);\n"
    "    const float3 zero = float3(0.0, 0.0, 0.0);\n"
    "    float op = floor(tu.params.x + 0.5);\n"
    "    // Materialize a before testing it. The ordered comparison has the same\n"
    "    // boundary as a <= 0, without a fused VTST multiply/writeback instruction.\n"
    "    if ((min(a, 0.0) == a) && (op <= 15 || op == 19 || op == 20 || op == 23 || op == 24)) {\n"
    "        return d4;\n"
    "    }\n"
    "    // Return each operation directly so later predicates cannot overwrite\n"
    "    // RGB values still needed by an earlier operation.\n"
    "    if (op == 1.0) { return float4(ps_mix(d, min(d + s, one), a), 1.0); }\n"
    "    else if (op == 2.0) { return float4(ps_mix(d, min(d, s), a), 1.0); }\n"
    "    else if (op == 3.0) { return float4(ps_mix(d, max(d, s), a), 1.0); }\n"
    "    else if (op == 4.0) { return float4(ps_mix(d, max(d + s - one, zero), a), 1.0); }\n"
    "    else if (op == 5.0) {\n"
    "        float3 raw = max(one - (one - d) / s, zero);\n"
    "        float3 r = float3(s.r > 0.0 ? raw.r : 0.0,\n"
    "                          s.g > 0.0 ? raw.g : 0.0,\n"
    "                          s.b > 0.0 ? raw.b : 0.0);\n"
    "        return float4(ps_mix(d, r, a), 1.0);\n"
    "    }\n"
    "    else if (op == 6.0) {\n"
    "        float3 k = max(one - s, zero);\n"
    "        float3 raw = min(d / k, one);\n"
    "        float3 r = float3(k.r > 0.0 ? raw.r : 1.0,\n"
    "                          k.g > 0.0 ? raw.g : 1.0,\n"
    "                          k.b > 0.0 ? raw.b : 1.0);\n"
    "        return float4(ps_mix(d, r, a), 1.0);\n"
    "    }\n"
    "    else if (op == 7.0) {\n"
    "        float3 k = max(one - a * s, zero);\n"
    "        float3 raw = min(d / k, one);\n"
    "        return float4(float3(d.r > 0.0 ? raw.r : 0.0,\n"
    "                   d.g > 0.0 ? raw.g : 0.0,\n"
    "                   d.b > 0.0 ? raw.b : 0.0), 1.0);\n"
    "    }\n"
    "    else if (op == 8.0) { return float4(ps_mix(d, abs(d - s), a), 1.0); }\n"
    "    else if (op == 9.0) { return float4(abs(d - a * s), 1.0); }\n"
    "    else if (op == 10.0) { return float4(ps_mix(d, d + s - 2.0 * d * s, a), 1.0); }\n"
    "    else if (op == 11.0 || op == 12.0) {\n"
    "        float3 h = s;\n"
    "        if (op == 12) { h = min(s / t.a, one); }\n"
    "        return float4(ps_hard_light(d, h, a), 1.0);\n"
    "    }\n"
    "    else if (op == 13.0) {\n"
    "        return float4(ps_overlay(d, s, a), 1.0);\n"
    "    }\n"
    "    else if (op == 14.0) {\n"
    "        float3 high = pow(d, one / (2.0 * s));\n"
    "        float3 low = pow(d, 2.0 - 2.0 * s);\n"
    "        float3 r = (s < float3(0.5, 0.5, 0.5)) ? low : high;\n"
    "        return float4(ps_mix(d, r, a), 1.0);\n"
    "    }\n"
    "    else if (op == 15.0) { return float4(max(d - a * (one - s), zero), 1.0); }\n"
    "    else if (op == 16.0) { return float4(min(d + s * ca, one), 1.0); }\n"
    "    else if (op == 17.0) { return float4(max(d - ca * (one - s), zero), 1.0); }\n"
    "    else if (op == 18.0) { return float4(s, 1.0); }\n"
    "    else if (op == 19.0) { return float4(ps_mix(d * d4.a, s, a), 1.0); }\n"
    "    else if (op == 20.0) { return float4(ps_mix(d, min(d, s), ca), 1.0); }\n"
    "    else if (op == 21.0) {\n"
    "        if (ca <= 0.0) { return d4; }\n"
    "        return float4(ps_mix(d, max(d, s), ca), 1.0);\n"
    "    }\n"
    "    else if (op == 22.0) { return float4(ps_mix(d, one - (one - d) * (one - s * ca), ca), 1.0); }\n"
    "    else if (op == 23.0) { return float4(min(d * s + (1.0 - a) * d, one), 1.0); }\n"
    "    else if (op == 24.0) { return float4(s, 1.0); }\n"
    "    return float4(d, 1.0);\n"
    "}\n"
    "\n"
    "float4 fs_ps(FragmentInput i) : COLOR {\n"
    "    return ps_apply(i, load_texel(tex1, int2(i.pos.xy), uTex1Size));\n"
    "}\n"
    "\n"
    "// Existing Hazuki nanovg_gxm_utils.h uses this exact native UCHAR4 declaration.\n"
    "// Raw target-register components are 0..255, unlike normalized texture samples.\n"
    "// Native GXP IDs1/9/97/105 independently confirm output metadata type7,4 lanes.\n"
    "#ifdef KNIFE_RUNTIME_NATIVE_FETCH\n"
    "unsigned char4 native_pack(float4 value) {\n"
    "    return unsigned char4(floor(clamp(value, float4(0.0, 0.0, 0.0, 0.0),\n"
    "                                      float4(1.0, 1.0, 1.0, 1.0)) * 255.0 + 0.5));\n"
    "}\n"
    "float4 native_unpack(unsigned char4 value) { return float4(value) / 255.0; }\n"
    "\n"
    "__nativecolor __regformat unsigned char4 fs_ps_fetch(FragmentInput i,\n"
    "    __regformat unsigned char4 destination : FRAGCOLOR) : COLOR {\n"
    "    return native_pack(ps_apply(i, native_unpack(destination)));\n"
    "}\n"
    "\n"
    "__nativecolor __regformat unsigned char4 fs_ps19_fetch(FragmentInput i,\n"
    "    __regformat unsigned char4 destination : FRAGCOLOR) : COLOR {\n"
    "    PsSample source = ps_source(i);\n"
    "    if (min(source.alpha, 0.0) == source.alpha) { return destination; }\n"
    "    float4 d = native_unpack(destination);\n"
    "    return native_pack(float4(ps_mix(d.rgb * d.a, source.source, source.alpha), 1.0));\n"
    "}\n"
    "\n"
    "#ifdef KNIFE_RUNTIME_PS_SPECIALIZED\n"
    "// The ordinary Sprite source subset of PsOp2. Keep the generic path's\n"
    "// destination-preserving zero-alpha branch and the same encoded RGBA8 pack.\n"
    "__nativecolor __regformat unsigned char4 fs_ps2_fetch(FragmentInput i,\n"
    "    __regformat unsigned char4 destination : FRAGCOLOR) : COLOR {\n"
    "    float4 t = tex2D(tex0, i.uv);\n"
    "    float3 s = t.rgb * i.color.rgb;\n"
    "    float a = t.a * i.color.a;\n"
    "    if (min(a, 0.0) == a) { return destination; }\n"
    "    float4 d = native_unpack(destination);\n"
    "    return native_pack(float4(ps_mix(d.rgb, min(d.rgb, s), a), 1.0));\n"
    "}\n"
    "\n"
    "__nativecolor __regformat unsigned char4 fs_ps19_group_fetch(FragmentInput i,\n"
    "    __regformat unsigned char4 destination : FRAGCOLOR) : COLOR {\n"
    "    float4 t = tex2D(tex0, i.uv);\n"
    "    float3 s = group_rgb(t.rgb) * i.color.rgb;\n"
    "    float a = group_alpha(t.a, tex2D(tex2, i.uv).a) * i.color.a;\n"
    "    if (min(a, 0.0) == a) { return destination; }\n"
    "    float4 d = native_unpack(destination);\n"
    "    return native_pack(float4(ps_mix(d.rgb * d.a, s, a), 1.0));\n"
    "}\n"
    "\n"
    "__nativecolor __regformat unsigned char4 fs_ps11_fetch(FragmentInput i,\n"
    "    __regformat unsigned char4 destination : FRAGCOLOR) : COLOR {\n"
    "    float4 t = tex2D(tex0, i.uv);\n"
    "    float3 s = t.rgb * i.color.rgb;\n"
    "    float a = t.a * i.color.a;\n"
    "    if (min(a, 0.0) == a) { return destination; }\n"
    "    float4 d = native_unpack(destination);\n"
    "    return native_pack(float4(ps_hard_light(d.rgb, s, a), 1.0));\n"
    "}\n"
    "\n"
    "__nativecolor __regformat unsigned char4 fs_ps13_fetch(FragmentInput i,\n"
    "    __regformat unsigned char4 destination : FRAGCOLOR) : COLOR {\n"
    "    float4 t = tex2D(tex0, i.uv);\n"
    "    float3 s = t.rgb * i.color.rgb;\n"
    "    float a = t.a * i.color.a;\n"
    "    if (min(a, 0.0) == a) { return destination; }\n"
    "    float4 d = native_unpack(destination);\n"
    "    return native_pack(float4(ps_overlay(d.rgb, s, a), 1.0));\n"
    "}\n"
    "\n"
    "// Ordinary op19 without haze/soft/rule/group. Stage clip_draw can prepare\n"
    "// this as Sprite, Fill or NoAlpha; retain both exact source-preparation flags.\n"
    "__nativecolor __regformat unsigned char4 fs_ps19_plain_fetch(FragmentInput i,\n"
    "    __regformat unsigned char4 destination : FRAGCOLOR) : COLOR {\n"
    "    float4 t = tex2D(tex0, i.uv);\n"
    "    if (tu.params2.z > 0.5) { t.a = 1.0; }\n"
    "    float3 s = tu.params.y > 0.5 ? i.color.rgb : t.rgb * i.color.rgb;\n"
    "    float a = t.a * i.color.a;\n"
    "    if (min(a, 0.0) == a) { return destination; }\n"
    "    float4 d = native_unpack(destination);\n"
    "    return native_pack(float4(ps_mix(d.rgb * d.a, s, a), 1.0));\n"
    "}\n"
    "#endif\n"
    "#endif\n"
    "#endif\n"
    ;
#endif
